INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1159, 159, 1, 'لا ريب أن من تدبر قول الله تعالى: ﴿ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ ﴾ [البقرة: 152]، وقوله جل وعلا: ﴿ وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ﴾ [الذاريات: 56]، ثم تأمل قوله ﷺ: «الدعاء هو العبادة»، سطعت له الحجة البينة، والدلالة الواضحة على أن من أفضل حالات العباد حالة ذكرهم لله رب العالمين، واشتغالهم من صميم الفؤاد، وجميع القلب، بالأذكار المأثورة، والأدعية المستفيضة عن سيد المرسلين، وخاتم النبيين، وخليل رب العالمين ﷺ.', 0, 'الأدعية المطلقة. (ص372)', '', '', 'لا ريب أن من تدبر قول الله تعالى ﴿ فٱذۡكروني أذۡكرۡكمۡ ﴾ البقرة 152 وقوله جل وعلا ﴿ وما خلقۡت ٱلۡجن وٱلۡإنس إلا ليعۡبدون ﴾ الذاريات 56 ثم تأمل قوله «الدعاء هو العبادة» سطعت له الحجة البينة والدلالة الواضحة على أن من أفضل حالات العباد حالة ذكرهم لله رب العالمين واشتغالهم من صميم الفؤاد وجميع القلب بالأذكار المأثورة والأدعية المستفيضة عن سيد المرسلين وخاتم النبيين وخليل رب العالمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1160, 159, 2, 'وقد حاولت هنا أن أجمع ما بلغته الطاقة من «أوراد الدعاء المطلق»؛ وهي الأدعية غير المقيدة بوظيفة ولا وقت ولا حال ولا مكان يدعو بها المسلم عمومًا، وفي أوقات مَظَنَّة الإجابة وأحوالها خصوصًا، وتحرَّيتُ أدعيةَ القرآن الكريم والسنة الشريفة؛ وذلك لأن صيغ الدعاء في الوحيين الشريفين جاءت فصيحة اللغة، متقاربة الألفاظ، متجانسة المعاني سهلة النطق على كل لسان يسيرة الحفظ على كل جَنان، فعلى الداعي أن يتقيد بها، ويواظب عليها، ويقدمها على ما سواها، وإذا ما طلع الصباح، فَأَطْفِئِ القِنْدِيلَ، واستغنِ عن المِصْبَاحِ، «وإذا جاءَ نَهْرُ اللهِ بَطَلَ نَهْرُ مَعْقِلٍ».', 0, 'الأدعية المطلقة. (ص372–373)

حاشية: وبعض هذه الدعوات مقتبس من نصوص الآيات القرآنية، وليست هي نصوص الآيات الكريمة نفسها، كما في رقمَيْ (١٨)، (٩٤).
وقد أضفتُ إليها ذلك النوع من الأدعية الموظفة التي تصلح صيغتها العامة للدعاء بها مطلقًا سواء في ذلك باب الثناء وباب السؤال، ولم أذكر من الأدعية ما هو خاص بحال معينة مثل: ﴿ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ٢٩ هَٰرُونَ أَخِي ﴾ [طه: 29، 30]، وأضفت إليها مثلها من الأدعية الموقوفة عن نَفَرٍ مِنَ الصحابة رضي الله عنهم أجمعين.
مثلٌ يُضرب لتحقير شيء إذا جاء ما هو أعظم منه وأكثر نفعًا، يريدون بنهر الله: البحر والمطر والسيل؛ فإنها تغلب سائر المياه وتَطِمُّ عليها، ونهر معقل: منسوب إلى معقل بن يسار المزني رضي الله عنه بالبصرة.', '', '', 'وقد حاولت هنا أن أجمع ما بلغته الطاقة من «أوراد الدعاء المطلق» وهي الأدعية غير المقيدة بوظيفة ولا وقت ولا حال ولا مكان يدعو بها المسلم عموما وفي أوقات مظنة الإجابة وأحوالها خصوصا وتحريت أدعية القرآن الكريم والسنة الشريفة وذلك لأن صيغ الدعاء في الوحيين الشريفين جاءت فصيحة اللغة متقاربة الألفاظ متجانسة المعاني سهلة النطق على كل لسان يسيرة الحفظ على كل جنان فعلى الداعي أن يتقيد بها ويواظب عليها ويقدمها على ما سواها وإذا ما طلع الصباح فأطفئ القنديل واستغن عن المصباح «وإذا جاء نهر الله بطل نهر معقل»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1161, 159, 3, 'وقد اجتهدتُ في ترتيبها وتنسيقها، ووزعتها على أحد عَشَرَ وِرْدًا حتى يمكنَ تقسيمُها حسب ظروفِ كل داعٍ، فيأتي ببعضِها في وقت، وببعضها في وقت آخَرَ بحيث يكون مواظبًا على مجموعها غيرَ هاجرٍ لبعضها.', 0, 'الأدعية المطلقة. (ص374)', '', '', 'وقد اجتهدت في ترتيبها وتنسيقها ووزعتها على أحد عشر وردا حتى يمكن تقسيمها حسب ظروف كل داع فيأتي ببعضها في وقت وببعضها في وقت آخر بحيث يكون مواظبا على مجموعها غير هاجر لبعضها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1176, 160, 1, 'قال تعالى: ﴿ وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡ ﴾ [غافر: 60].', 0, 'فضيلة الدعاء. (ص375)', '', '', 'قال تعالى ﴿ وقال ربكم ٱدۡعوني أسۡتجبۡ لكمۡ ﴾ غافر 60', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1177, 160, 2, 'وقال عز وجل: ﴿ وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِ ﴾ [البقرة: 186].', 0, 'فضيلة الدعاء. (ص375)', '', '', 'وقال عز وجل ﴿ وإذا سألك عبادي عني فإني قريبۖ أجيب دعۡوة ٱلداع إذا دعان ﴾ البقرة 186', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1178, 160, 3, 'وعن النعمان بن بشير رضي الله عنهما قال رسول الله ﷺ: «الدعاء هو العبادة»، ثم قرأ: ﴿ وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴾ [غافر: 60].', 0, 'فضيلة الدعاء. (ص375)', '', '', 'وعن النعمان بن بشير رضي الله عنهما قال رسول الله «الدعاء هو العبادة» ثم قرأ ﴿ وقال ربكم ٱدۡعوني أسۡتجبۡ لكمۡۚ إن ٱلذين يسۡتكۡبرون عنۡ عبادتي سيدۡخلون جهنم داخرين ﴾ غافر 60', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1525, 160, 4, 'وقال زكريا عليه السلام: ﴿ وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ﴾ الآية [مريم: 4]، معناه: «لم أزل بدعائك سعيدًا، لم تردده علي»، وقيل: «قد كنتَ عوَّدتَني الإجابةَ فيما مضى»، وقيل: «لم أدعُكَ قطُّ فخيَّبتَني فيما مضى، فتُخيّبَني فيما بقي».', 0, 'فضيلة الدعاء. (ص375)', '', '', 'وقال زكريا عليه السلام ﴿ ولمۡ أكنۢ بدعآئك رب شقيا ﴾ الآية مريم 4 معناه «لم أزل بدعائك سعيدا لم تردده علي» وقيل «قد كنت عودتني الإجابة فيما مضى» وقيل «لم أدعك قط فخيبتني فيما مضى فتخيبني فيما بقي»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1526, 160, 5, 'وإني لأرجو الله حتى كأنني أرى بجميل الظن ما الله صانع', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وإني لأرجو الله حتى كأنني أرى بجميل الظن ما الله صانع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1179, 160, 6, 'وعن ابن عباس، وأبي هريرة، والنعمان بن بشير رضي الله عنهم، قال رسول الله ﷺ: «أفضل العبادة الدعاء».', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وعن ابن عباس وأبي هريرة والنعمان بن بشير رضي الله عنهم قال رسول الله «أفضل العبادة الدعاء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1180, 160, 7, 'وعن أبي هريرة رضي الله عنه، قال رسول الله ﷺ: «ليس شيء أكرم على الله تعالى من الدعاء».', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وعن أبي هريرة رضي الله عنه قال رسول الله «ليس شيء أكرم على الله تعالى من الدعاء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1181, 160, 8, 'وعن ابن عمر رضي الله عنهما قال رسول الله ﷺ: «إن الدعاء ينفع مما نزل، ومما لم ينزل، فعليكم عباد الله بالدعاء».', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وعن ابن عمر رضي الله عنهما قال رسول الله «إن الدعاء ينفع مما نزل ومما لم ينزل فعليكم عباد الله بالدعاء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1182, 160, 9, 'وعن سلمان الفارسي رضي الله عنه، قال رسول الله ﷺ: «إن ربكم حيي كريم يستحيي من عبده إذا رفع يديه إليه أن يردهما صفرًا خائبتين».', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وعن سلمان الفارسي رضي الله عنه قال رسول الله «إن ربكم حيي كريم يستحيي من عبده إذا رفع يديه إليه أن يردهما صفرا خائبتين»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1183, 160, 10, 'وعنه رضي الله عنه قال رسول الله ﷺ: «لا يرد القضاء إلا الدعاء، ولا يزيد في العمر إلا البر».', 0, 'فضيلة الدعاء. (ص376)', '', '', 'وعنه رضي الله عنه قال رسول الله «لا يرد القضاء إلا الدعاء ولا يزيد في العمر إلا البر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1184, 160, 11, 'وعن أبي هريرة رضي الله عنه قال رسول الله ﷺ: «إنه من لم يسأل الله تعالى يغضب عليه».', 0, 'فضيلة الدعاء. (ص377)

حاشية: وذلك لأنه إما قانط وإما متكبر، وكل واحد من الأمرين مُوجبٌ للغضب، قال تعالى: ﴿ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴾ [غافر: 60]، أي: عن دعائي، فهو سبحانه يحب أن يُسأل وأن يُلَحَّ عليه، ومن لم يسأله يُبغضه، والمبغوض مغضوب عليه.
وسواء استُجيبَ الدعاءُ أم لم يُستجبْ فعلينا أن ندعو خشيةَ غضبِ اللهِ علينا إذا هجرنا دعاءه عَزَّ وجَلَّ، فكيف لو علمنا أنه مَرْضاة لله سبحانه، ومجلبة للخير، ومَنْجاة من الشر؟!', '', '', 'وعن أبي هريرة رضي الله عنه قال رسول الله «إنه من لم يسأل الله تعالى يغضب عليه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1527, 160, 12, 'ومع أن الدعاء وسيلة لتحصيل أعظم خيرات الدنيا والآخرة وبركاتهما، فإنه عبادة سهلة يسيرة لا تُكلِّفُ جُهدًا، ولا تُلحِقُ بالداعي مشقَّةً؛ ولذلك كان التواني فيه أشدَّ العجزِ، ومَن عجز عنه –مع سهولته– فهو عن غيره أعجزُ.', 0, 'فضيلة الدعاء. (ص377)', '', '', 'ومع أن الدعاء وسيلة لتحصيل أعظم خيرات الدنيا والآخرة وبركاتهما فإنه عبادة سهلة يسيرة لا تكلف جهدا ولا تلحق بالداعي مشقة ولذلك كان التواني فيه أشد العجز ومن عجز عنه –مع سهولته– فهو عن غيره أعجز', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1185, 160, 13, 'عن أبي هريرة رضي الله عنه، قال: قال رسول الله ﷺ: «أعجز الناس من عجز عن الدعاء، وأبخل الناس من بخل بالسلام».', 0, 'فضيلة الدعاء. (ص377–378)

حاشية: «أعجز الناس» أي: من أضعفهم رأيًا وأعماهم بصيرةً «من عجز عن الدعاء»: أي: الطلب من الله تعالى، لا سيما عند الشدائد؛ لتركه ما أمره الله به، وتعرضه لغضبه بإهماله ما لا مشقة عليه فيه، وفيه قيل:
لا تسألنَّ بُنَيَّ آدمَ حاجةً
وسَلِ الذي أبوابُه لا تُحجَبُ
اللهُ يغضب إن تركتَ سؤالَه
وبُنَيُّ آدمَ حين يُسألُ يَغضَبُ
وفي هذا الحديث ردٌّ على من زعم أن الأَوْلَى عدمُ الدعاء. وما أحسنَ ما قال سُفْيانُ الثَّوريُّ رحمه الله: «يا مَن أحبَّ عبادِه إليه مَن سأله، فأكثرَ سؤالَه، ويا مَنْ أبغضُ عبادِه إليه مَن لم يسأله، وليس كذلك غيرُكَ يا ربِّ».
«وأبخل الناس» أي: أمنعهم للفضل، وأشحُّهم بالبذل، «من بخل بالسلام» على مَن يعرفهم ومن لا يعرفهم؛ فإنه خفيف المؤنة عظيم المثوبة، فلا يمله إلا من بخل بالقربات، وشَحَّ بالمثوبات، وتهاوَنَ بمراسم الشريعة ومن بَخِلَ بمجرد النطق بالسلام على مَن لقيه فهو أبخل مِن كل بخيل، لأن السلامَ ليس فيه بذلُ مالٍ.', '', '', 'عن أبي هريرة رضي الله عنه قال قال رسول الله «أعجز الناس من عجز عن الدعاء وأبخل الناس من بخل بالسلام»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1507, 166, 1, 'يوم عرفة من السَّنة، ورمضان من الشهور، ويوم الجمعة من الأسبوع في آخر ساعة بعد العصر إذا جلس ينتظر صلاةَ المغرب.', 0, 'أوقات إجابة الدعاء. (ص379)', '', '', 'يوم عرفة من السنة ورمضان من الشهور ويوم الجمعة من الأسبوع في آخر ساعة بعد العصر إذا جلس ينتظر صلاة المغرب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1508, 166, 2, 'يوم الأربعاء بين صلاتَيِ الظهر والعصر.', 0, 'أوقات إجابة الدعاء. (ص379)', '', '', 'يوم الأربعاء بين صلاتي الظهر والعصر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1509, 166, 3, 'جوف الليل الآخِر، ونصفه الثاني، وثلثه الأول، وثلثه الأخير، ووقت السَّحَر.', 0, 'أوقات إجابة الدعاء. (ص379)', '', '', 'جوف الليل الآخر ونصفه الثاني وثلثه الأول وثلثه الأخير ووقت السحر', '', '');
