UPDATE contents SET body = 'قال تعالى: ﴿ وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡ ﴾. [غافر: ٦٠]', search = 'قال تعالى ﴿ وقال ربكم ٱدۡعوني أسۡتجبۡ لكمۡ ﴾ غافر ٦٠' WHERE id = 1176;
UPDATE contents SET body = 'وعنه رضي الله عنه قال رسول الله ﷺ: «لا يرد القضاء إلا الدعاء ولا يزيد في العمر إلا البر».', search = 'وعنه رضي الله عنه قال رسول الله «لا يرد القضاء إلا الدعاء ولا يزيد في العمر إلا البر»' WHERE id = 1183;
UPDATE contents SET source = 'فضيلة الدعاء. (ص377–378)

حاشية: «أعجز الناس» أي: من أضعفهم رأيًا وأعماهم بصيرةً «من عجز عن الدعاء»: أي: الطلب من الله تعالى، لا سيما عند الشدائد؛ لتركه ما أمره الله به، وتعرضه لغضبه بإهماله ما لا مشقة عليه فيه، وفيه قيل:
لا تسألنَّ بُنَيَّ آدمَ حاجةً
وسَلِ الذي أبوابُه لا تُحجَبُ
اللهُ يغضب إن تركتَ سؤالَه
وبُنَيُّ آدمَ حين يُسألُ يَغضَبُ
وفي هذا الحديث ردٌّ على من زعم أن الأَوْلَى عدمُ الدعاء. وما أحسنَ ما قال سُفْيانُ الثَّوريُّ رحمه الله: «يا مَن أَحَبُّ عبادِه إليه مَن سأله، فأكثرَ سؤالَه، ويا مَنْ أبغضُ عبادِه إليه مَن لم يسأله، وليس كذلك غيرُكَ يا ربِّ».
«وأبخل الناس» أي: أمنعهم للفضل، وأشحُّهم بالبذل، «من بخل بالسلام» على مَن يعرفهم ومن لا يعرفهم؛ فإنه خفيف المؤنة عظيم المثوبة، فلا يمله إلا من بخل بالقربات، وشَحَّ بالمثوبات، وتهاوَنَ بمراسم الشريعة ومن بَخِلَ بمجرد النطق بالسلام على مَن لقيه فهو أبخل مِن كل بخيل، لأن السلامَ ليس فيه بذلُ مالٍ.' WHERE id = 1185;
